# Surah Hud (chapter 11) — part 1: ayat 1-10 (IDs 1474-1483)
SURAH = 11

ENTRIES = {
1474: (
"بسم اللہ الرحمٰن الرحیم — الر — یہ — کتاب ہے — جس — کی آیات — محکم کی گئیں — پھر — تفصیل کے ساتھ — بیان کی گئیں — ایک حکمت والے — خبر رکھنے والے — کی طرف سے",
"""۱۔ سورہ ہود — محکم آیات — اور تفصیل۔
۲۔ ’’الر كِتَابٌ أُحْكِمَتْ آيَاتُهُ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ‘‘ — الر — یہ — کتاب ہے — جس — کی آیات — محکم کی گئیں — پھر — تفصیل کے ساتھ — بیان کی گئیں — ایک حکمت والے — خبر رکھنے والے — کی طرف سے — یعنی یہ کتاب — محکم آیات والی — ایک — حکمت والے کے پاس سے آئی ہے۔
۳۔ عملی سبق: قرآن — محکم اور مفصل ہے؛ اس کی — پیروی کرو۔"""
),
1475: (
"یہ کہ — تم — اللہ کے سوا — کسی کی عبادت — نہ کرو — بے شک — میں — تمہارے لیے — اس — کی طرف سے — ڈرانے والا — اور خوشخبری — دینے والا — ہوں",
"""۱۔ صرف اللہ کی عبادت — کرو — نبیؐ مبشر اور نذیر۔
۲۔ ’’أَلَّا تَعْبُدُوا إِلَّا اللَّهَ إِنَّنِي لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ‘‘ — یہ کہ — تم — اللہ کے سوا — کسی کی عبادت — نہ کرو — بے شک — میں — تمہارے لیے — اس — کی طرف سے — ڈرانے والا — اور خوشخبری — دینے والا — ہوں — یعنی صرف اللہ کی عبادت — کرو — میں تمہارے لیے — ڈرانے والا اور خوشخبری دینے والا — ہوں۔
۳۔ عملی سبق: عبادت — صرف اللہ کی کرو؛ رسولؐ — مبشر اور نذیر ہیں۔"""
),
1476: (
"اور — یہ کہ — تم — اپنے رب سے — استغفار کرو — پھر — اس کی طرف — توبہ کرو — وہ — تمہیں — ایک — مقررہ مدت — تک — اچھی طرح — فائدہ — دے گا — اور — ہر — فضل والے کو — اس — کا — فضل — دے گا — اور — اگر — تم — منہ موڑو — تو — میں — تم — پر — ایک بڑے دن — کے عذاب — سے ڈرتا ہوں",
"""۱۔ استغفار اور توبہ — اللہ کی مغفرت — کا ذریعہ۔
۲۔ ’’وَأَنِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُمَتِّعْكُم مَّتَاعًا حَسَنًا إِلَىٰ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ وَإِن تَوَلَّوْا فَإِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ‘‘ — اور — یہ کہ — تم — اپنے رب سے — استغفار کرو — پھر — اس کی طرف — توبہ کرو — وہ — تمہیں — ایک — مقررہ مدت — تک — اچھی طرح — فائدہ — دے گا — اور — ہر — فضل والے کو — اس — کا — فضل — دے گا — اور — اگر — تم — منہ موڑو — تو — میں — تم — پر — ایک بڑے دن — کے عذاب — سے ڈرتا ہوں — یعنی استغفار اور توبہ — کرو — اللہ — تمہیں دنیا میں — اچھی طرح فائدہ دے گا — اور ہر فضل والے کو اس کا — فضل دے گا — اور منہ پھیرنے پر — ایک بڑے دن کا عذاب — ہے۔
۳۔ عملی سبق: استغفار — مسلسل کرو؛ توبہ — زندگی میں — سدا — کرو۔"""
),
1477: (
"اللہ — کی طرف — تم — سب — لوٹ کر جاؤ گے — اور — وہ — ہر چیز — پر — قادر ہے",
"""۱۔ سب لوٹ کر اللہ — کی طرف — جائیں گے۔
۲۔ ’’إِلَى اللَّهِ مَرْجِعُكُمْ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اللہ — کی طرف — تم — سب — لوٹ کر جاؤ گے — اور — وہ — ہر چیز — پر — قادر ہے — یعنی سب — اللہ — کے پاس — لوٹ کر جائیں گے — اور وہ ہر چیز — پر قادر ہے۔
۳۔ عملی سبق: اللہ — کی طرف لوٹنا — ہوگا؛ ہر کام — اسی کے — ہاتھ میں ہے۔"""
),
1478: (
"سنو — وہ — اپنے سینے — موڑتے ہیں — تاکہ — اس — سے چھپ جائیں — سنو — جس وقت — وہ — اپنے کپڑے — اوڑھتے ہیں — وہ — جانتا ہے — جو — وہ — چھپاتے ہیں — اور جو — ظاہر کرتے ہیں — بے شک — وہ — سینوں کی باتیں — جاننے والا — ہے",
"""۱۔ اللہ — سینوں کی — چھپی — باتیں — بھی جانتا ہے۔
۲۔ ’’أَلَا إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا مِنْهُ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ‘‘ — سنو — وہ — اپنے سینے — موڑتے ہیں — تاکہ — اس — سے چھپ جائیں — سنو — جس وقت — وہ — اپنے کپڑے — اوڑھتے ہیں — وہ — جانتا ہے — جو — وہ — چھپاتے ہیں — اور جو — ظاہر کرتے ہیں — بے شک — وہ — سینوں کی باتیں — جاننے والا — ہے — یعنی لوگ چھپ کر — اللہ سے بچنا — چاہتے ہیں — کپڑوں میں بھی — اللہ — ان کے راز — جانتا ہے۔
۳۔ عملی سبق: اللہ — ہر راز — جانتا ہے؛ دل — صاف — رکھو۔"""
),
1479: (
"اور — زمین پر — کوئی — جاندار — ایسا — نہیں — جس کا رزق — اللہ — کے — ذمے — نہ ہو — اور — وہ — اس — کا — ٹھکانہ — اور — اس — کی — امانت کی جگہ — جانتا ہے — سب — ایک — واضح کتاب — میں ہے",
"""۱۔ ہر جاندار کا رزق — اللہ — کے ذمے ہے۔
۲۔ ’’وَمَا مِن دَابَّۃٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِي كِتَابٍ مُّبِينٍ‘‘ — اور — زمین پر — کوئی — جاندار — ایسا — نہیں — جس کا رزق — اللہ — کے — ذمے — نہ ہو — اور — وہ — اس — کا — ٹھکانہ — اور — اس — کی — امانت کی جگہ — جانتا ہے — سب — ایک — واضح کتاب — میں ہے — یعنی ہر جاندار کا رزق — اللہ — کے ذمے ہے — اور — وہ — ہر ایک کا ٹھکانہ اور محفوظ جگہ — جانتا ہے؛ سب ایک واضح کتاب میں — ہے۔
۳۔ عملی سبق: رزق — کی فکر — اللہ پر چھوڑو؛ محنت — کرو — توکل — کرو۔"""
),
1480: (
"اور — وہ — وہی — ہے — جس — نے — آسمان اور زمین — کو — چھ دن میں — بنایا — اور — اس کا عرش — پانی — پر — تھا — تاکہ — وہ — تمہیں — آزمائے — کہ — تم میں سے — سب سے اچھا عمل — کون کرتا ہے — اور — اگر — آپ کہیں — کہ — تم — موت کے بعد — اٹھائے جاؤ گے — تو — کافر — ضرور — کہیں گے — یہ — تو — واضح جادو ہے",
"""۱۔ آسمان و زمین کا خالق — اللہ — چھ دن میں — عرش پانی پر — آزمائش — کے لیے۔
۲۔ ’’وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّۃِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِن بَعْدِ الْمَوْتِ لَيَقُولَنَّ الَّذِينَ كَفَرُوا إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ‘‘ — اور — وہ — وہی — ہے — جس — نے — آسمان اور زمین — کو — چھ دن میں — بنایا — اور — اس کا عرش — پانی — پر — تھا — تاکہ — وہ — تمہیں — آزمائے — کہ — تم میں سے — سب سے اچھا عمل — کون کرتا ہے — اور — اگر — آپ کہیں — کہ — تم — موت کے بعد — اٹھائے جاؤ گے — تو — کافر — ضرور — کہیں گے — یہ — تو — واضح جادو ہے — یعنی اللہ — نے چھ دن میں آسمان و زمین — بنایا — عرش پانی پر تھے — اور یہ — آزمائش ہے؛ موت کے بعد — اٹھانے پر — کافر — جادو — کہتے ہیں۔
۳۔ عملی سبق: زندگی — ایک آزمائش — ہے؛ بہترین عمل — کرو۔"""
),
1481: (
"اور — اگر — ہم — ان — سے — عذاب — کو — ایک — مقررہ مدت — تک — موخر کر دیں — تو — وہ — ضرور — کہیں گے — کس چیز — نے — اس — کو — روک رکھا ہے — سنو — جس — دن — وہ — ان — کے پاس — آئے گا — وہ — ان — سے — ہٹایا نہیں جا سکے گا — اور — وہ — چیز — جن — کا — وہ — مذاق اڑاتے تھے — ان — کو — گھیر لے گی",
"""۱۔ عذاب تاخیر — کفار غیب سمجھتے ہیں — مگر آ کے رہے گا۔
۲۔ ’’وَلَئِنْ أَخَّرْنَا عَنْهُمُ الْعَذَابَ إِلَىٰ أُمَّۃٍ مَّعْدُودَۃٍ لَّيَقُولُنَّ مَا يَحْبِسُهُ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ‘‘ — اور — اگر — ہم — ان — سے — عذاب — کو — ایک — مقررہ مدت — تک — موخر کر دیں — تو — وہ — ضرور — کہیں گے — کس چیز — نے — اس — کو — روک رکھا ہے — سنو — جس — دن — وہ — ان — کے پاس — آئے گا — وہ — ان — سے — ہٹایا نہیں جا سکے گا — اور — وہ — چیز — جن — کا — وہ — مذاق اڑاتے تھے — ان — کو — گھیر لے گی — یعنی عذاب کی تاخیر — مذاق نہیں ہمارے صبر کی — وجہ سے ہے؛ جس دن آئے گا — ہٹایا نہیں جا سکے گا۔
۳۔ عملی سبق: عذاب — تاخیر — اللہ کی حکمت ہے؛ بے پروائی — مت کرو۔"""
),
1482: (
"اور — اگر — ہم — انسان کو — اپنی — طرف سے — رحمت — کا مزہ — چکھائیں — پھر — اس — کو — اس سے — چھین لیں — تو — وہ — یقیناً — مایوس — ناشکرا — ہو جاتا ہے",
"""۱۔ انسان — نعمت — ملے تو — خوش — پھر چھن جائے تو ناامید اور ناشکرا۔
۲۔ ’’وَلَئِنْ أَذَقْنَا الْإِنسَانَ مِنَّا رَحْمَۃً ثُمَّ نَزَعْنَاهَا مِنْهُ إِنَّهُ لَيَئُوسٌ كَفُورٌ‘‘ — اور — اگر — ہم — انسان کو — اپنی — طرف سے — رحمت — کا مزہ — چکھائیں — پھر — اس — کو — اس سے — چھین لیں — تو — وہ — یقیناً — مایوس — ناشکرا — ہو جاتا ہے — یعنی انسان — رحمت — ملے تو خوش ہوتا ہے — چھن جائے — تو ناامید اور ناشکرا — ہو جاتا ہے۔
۳۔ عملی سبق: نعمت — عارضی ہے؛ شکر — ہمیشہ کرو۔"""
),
1483: (
"اور — اگر — ہم — اس — کو — کسی — تکلیف کے بعد — خوش حالی — چکھائیں — تو — وہ — ضرور کہے — برائی — مجھ — سے — چلی گئی — بے شک — وہ — بہت خوش — فخر کرنے والا — ہے",
"""۱۔ خوشحالی — ملنے پر — انسان — فخر — کرتا ہے۔
۲۔ ’’وَلَئِنْ أَذَقْنَاهُ نَعْمَاءَ بَعْدَ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ السَّيِّئَاتُ عَنِّي إِنَّهُ لَفَرِحٌ فَخُورٌ‘‘ — اور — اگر — ہم — اس — کو — کسی — تکلیف کے بعد — خوش حالی — چکھائیں — تو — وہ — ضرور کہے — برائی — مجھ — سے — چلی گئی — بے شک — وہ — بہت خوش — فخر کرنے والا — ہے — یعنی تکلیف کے بعد — خوشحالی — ملے تو انسان — کہتا ہے برائیں — چلی گئیں — اور وہ — فخر کرنے لگتا ہے۔
۳۔ عملی سبق: خوشحالی — رب کی نعمت ہے؛ غرور نہیں — شکر — کرو۔"""
),
}
